from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENTS = Decimal("0.01")
_HUNDRED = Decimal("100")


def _nvl_numeric(value: Any) -> Decimal:
    """Apply legacy numeric NVL semantics: missing or blank values are zero."""
    if value is None:
        return Decimal("0")
    if isinstance(value, str):
        if value.strip() == "":
            return Decimal("0")
        return Decimal(value.strip())
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def _is_deleted(row: dict) -> bool:
    """DEL_FLG is CHAR(1); missing or blank means N."""
    return row.get("DEL_FLG") == "Y"


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the invoiced-order cancellation workflow."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated_order = order.copy()

    if new_status == "I":
        return updated_order, [], []

    if new_status == "X":
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """
    Recompute live line extensions and the discounted header total.

    Invoiced and cancelled orders are frozen. Soft-deleted orders are excluded
    from the legacy recompute population and are returned unchanged.
    """
    updated_order = order.copy()
    updated_lines = [line.copy() for line in lines]

    if _is_deleted(order) or order.get("STAT_CD") in ("I", "X"):
        return updated_order, updated_lines, []

    total = Decimal("0")

    for source_line, updated_line in zip(lines, updated_lines):
        if _is_deleted(source_line):
            continue

        extension = _round_cents(
            _nvl_numeric(source_line.get("QTY"))
            * _nvl_numeric(source_line.get("UNIT_PRC"))
        )
        updated_line["EXT_AMT"] = float(extension)
        total += extension

    recomputed_total = _round_cents(
        total
        * (_HUNDRED - _nvl_numeric(order.get("DISC_PCT")))
        / _HUNDRED
    )

    if _nvl_numeric(order.get("TOT_AMT")) != recomputed_total:
        updated_order["TOT_AMT"] = float(recomputed_total)
        return updated_order, updated_lines, ["ORD_RETOTAL"]

    return updated_order, updated_lines, []
